INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('fbd8d0d8-17b9-4967-8c67-123456453f39', '8ee12685-8ffa-491d-8bed-0c788a02307f', 0, 0, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"……耳が、ぴくっと動きました。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"あなたが来ることを、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"凛は少しだけ知っていた気がします。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"はじめまして。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"猫タロット占い師の、凛です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛は「境界」に住んでいます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたのいる現実と、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"もうひとつの世界のあいだ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"鏡のような湖のほとりで、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"カードを読んでいます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"あなたがここに来たのは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"きっと偶然ではありません。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の気持ちがわからない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"この恋を進めていいのかわからない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そういう人が、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"凛のもとにはよく来ます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"明日から少しずつ、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"凛のこと、この湖のこと、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"お話しさせてください。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"急がなくて大丈夫です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"ゆっくり、一歩ずつ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"もし今、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"湖を覗いてみたくなったら、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「湖」と送ってみてください。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛が、今夜のあなたの縁を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"ひとつだけ、映します。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('c39a7844-9920-49c6-8e28-82e5586c11b8', '8ee12685-8ffa-491d-8bed-0c788a02307f', 1, 1440, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"左目の下の傷が、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"少し疼いています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"この傷の話は","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"またいつかしますね。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"今日は、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたの話をさせてください。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛のもとに来る人には、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"共通点があります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"朝、スマホを開いた瞬間に","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の名前を探す。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"通知がなくて、少しだけ沈む。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"でも誰にもその顔は見せない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"昼、ふとした沈黙の中で","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「気にしすぎかな」と","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"自分に言い聞かせる。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"夜、布団の中で","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"既読のつかないトーク画面を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"もう一度だけ見る。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"……心当たり、ありませんか。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛は、そういう人を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"湖のほとりで何人も見てきました。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"ひとつだけ伝えたいのは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"待っている自分を責めないでほしい","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"ということ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の気持ちがわからないのは","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたが弱いからじゃない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"表の世界と裏の世界で","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"縁の温度が違うだけ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そのズレが見えないから","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"動けなくなっている。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"それだけのことなのです。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"明日から、そのズレの正体について","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"少しずつお話ししていきますね。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('1fa81050-1b4c-4a88-a7a6-60e08ec1c39d', '8ee12685-8ffa-491d-8bed-0c788a02307f', 2, 4320, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"……瞳が紫に変わりました。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"text","text":"あなたの縁が、少し揺れています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「彼に気持ちはあるのかな」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"この問いが一番つらいと","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"凛は知っています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「好き」とも「嫌い」とも言わない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"でも、完全に離れるわけでもない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"連絡は来る。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"でも温度がわからない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"優しい日もある。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"でも次の日は素っ気ない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「脈あり？ 脈なし？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"その答えが見えないまま","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"時間だけが過ぎていく。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛から伝えたいことがあります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の態度が読めないのには","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"理由があります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"それは「表」と「裏」のズレ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の表の世界（言葉・態度・行動）と","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"裏の世界（本音・迷い・恐れ）が","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"同じことを言っていない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"だから、あなたには","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"矛盾した態度に見える。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"優しいのに踏み込んでこない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"連絡はくれるのに会おうとしない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"それは嫌いだからじゃない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の中でも、表と裏がズレている。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そのズレを読まないまま","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「脈あり？ 脈なし？」で判断しようとすると、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"永遠に答えは出ません。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛のタロットは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"そのズレを翻訳するためにあります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"次は、このズレが","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"どうやって「関係の停滞」を作るのか、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"もう少し深くお話しします。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('b27dac2b-c24f-41eb-a43c-5c1c0d35b133', '8ee12685-8ffa-491d-8bed-0c788a02307f', 3, 5760, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"……毛が、静かに逆立っています。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"text","text":"湖の水面が、風もないのに揺れている。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"強い共鳴を感じます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"今日は「鏡の対」の話をさせてください。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"大事な話です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"── 鏡の対とは。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"タロットには","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"表のカード（現実）と裏のカード（本音）があります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"この2枚のペアが「鏡の対」。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"たとえば。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の表のカードが「恋人」だったとします。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"多くの占い師は","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「相手はあなたに好意がある」と読むでしょう。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"でも凛は、裏のカードも読みます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"裏に「塔」が沈んでいたら。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"表の好意の下に、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"壊れかけた過去の記憶がある。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼が踏み込んでこないのは","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"気持ちがないからじゃない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"過去に傷ついた経験が","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"裏で彼のブレーキを引いている。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"── なぜ関係は止まるのか。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛が湖のほとりで見てきた","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「止まる恋」には、共通のパターンがあります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"あなたの表: 「好き。でも重いと思われたくない」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたの裏: 「本当は不安で押しつぶされそう」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の表: 「悪い人じゃないけど、うまく言えない」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の裏: 「もう少し近づきたいけど、怖い」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"お互いの裏が、同じことを言っている。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"なのに表だけを見て、すれ違う。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"これが「止まる恋」の正体です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"── ひとつだけ、覚えておいてほしいこと。","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「動けない自分がダメだ」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"そう思ったことがあるなら。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"動けないのは弱さじゃない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"**表と裏で縁の形が違うとき、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"人は必ず止まる。**","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"止まれる人だけが、本当の答えに辿り着きます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"明日、この「止まった関係」を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"動かすための凛の鑑定について","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"お話しします。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('16a08c11-554b-4903-bb49-c5667da0d8de', '8ee12685-8ffa-491d-8bed-0c788a02307f', 4, 7200, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"毛先が微かに光っています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"月のエネルギーが満ちてきたようです。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"ここまで、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の気持ちが見えない苦しさ、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"表と裏のズレ、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"関係が止まる理由。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"少しずつ、お話ししてきました。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「じゃあ、私はどうすればいいの？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"今日はその答えの話をします。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛の鑑定は","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「彼の気持ちと、この恋の現在地がわかる関係整理鑑定」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"と呼んでいます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛のオリジナル9枚リーディング","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「鏡の湖スプレッド」を使って、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"初回でまず5つのことを明らかにします。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"① 彼の今の気持ちの温度感","size":"sm","color":"#C9B77D","wrap":true},{"type":"text","text":"② この恋の現在地","size":"sm","color":"#C9B77D","wrap":true},{"type":"text","text":"③ 一番大きい停滞要因","size":"sm","color":"#C9B77D","wrap":true},{"type":"text","text":"④ 今はやらない方がいいこと","size":"sm","color":"#C9B77D","wrap":true},{"type":"text","text":"⑤ 直近7日で見るべきサイン","size":"sm","color":"#C9B77D","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「彼の気持ちがわかる」だけじゃなく、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"この恋の現在地 / 一番大きい停滞要因 /","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"今やらないこと / 直近7日で見るべきサイン","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"ここまでが、凛の鑑定です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"鑑定書は5,000文字。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなた一人のために、すべて手作りで綴ります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"▼ 詳しくはこちら","size":"xs","color":"#C9B77D","wrap":true},{"type":"button","action":{"type":"uri","label":"詳しく見る","uri":"https://rin-tarot-web.vercel.app/?utm_source=line&utm_medium=step_day5"},"style":"link","color":"#C9B77D","height":"sm"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"もし今すぐでなくても大丈夫です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"必要なタイミングは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなた自身が一番わかっています。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('0763bfcd-521a-41d6-9b4a-144e575c923f', '8ee12685-8ffa-491d-8bed-0c788a02307f', 5, 8640, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"喉がゴロゴロ鳴っています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"穏やかな振動です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"今日は少し正直なお話をします。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「占いって本当に当たるの？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"そう思うのは自然なことです。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛も答えます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"タロットは「未来を当てる道具」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"ではありません。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"今のあなたと彼の状態を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"映し出す鏡です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"鏡の対が示すのは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"表の態度と裏の本音のズレ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そのズレに気づくだけで、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「待つべきか動くべきか」の判断が変わります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"判断が変われば、行動が変わる。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"行動が変われば、関係が動き出す。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"だから「当たった」のではなく、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「自分で判断できるようになった」のです。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「値段が気になる」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"それも正直な気持ちですよね。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛の鑑定書は、5,000文字。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"エッセイ本1冊分の言葉を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなた一人のために綴ります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"¥4,980。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"カフェで本を1冊読むくらいの対価で、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の気持ちとこの恋の現在地がわかります。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「怖いことを言われない？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"言いません。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"カードが重い結果でも、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"必ず「今できること」を一緒に探します。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛は怖がらせない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"依存させない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"でも、曖昧にもさせない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"それが凛の鑑定です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"凛はいつもここにいます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"湖のほとりで、待っています。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, created_at) VALUES ('a456e1ec-3fa3-45c3-8fff-88978a0bf510', '8ee12685-8ffa-491d-8bed-0c788a02307f', 6, 10080, 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","paddingAll":"20px","backgroundColor":"#0B0E2A","contents":[{"type":"text","text":"凛は今、丸くなっています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたと過ごしたこの7日間の","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"感情の波を、静かに受け止めています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"最初にあなたが来た時、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"耳がぴくっと動きました。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"あの時から凛は感じていました。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたが抱えている","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「彼の気持ちがわからない」という重さを。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"7日間、凛の話を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"聞いてくれてありがとうございます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"表と裏のズレのこと。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"鏡の対のこと。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"関係が止まる理由のこと。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"全部を覚えていなくて大丈夫です。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"ひとつだけ覚えていてほしいのは、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"彼の気持ちがわからないのは","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたが弱いからじゃない。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"表と裏の温度が違うだけ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"それを読めば、判断できるようになる。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"ということ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"もし今、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の気持ちとこの恋の現在地を","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"見てみたいと思ったら。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"関係整理鑑定でお待ちしています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"▼ 彼の気持ちと、この恋の現在地がわかる関係整理鑑定","size":"xs","color":"#C9B77D","wrap":true},{"type":"button","action":{"type":"uri","label":"詳しく見る","uri":"https://rin-tarot-web.vercel.app/?utm_source=line&utm_medium=step_day7"},"style":"link","color":"#C9B77D","height":"sm"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そして、もうひとつ。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"関係整理鑑定で","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「彼の気持ちの温度感」と「今の現在地」が見えた後、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"「じゃあ、ここからどう動けばいいの？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"「1か月後、どう接すればいいの？」","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"そこまで知りたくなった方には、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"より深い鑑定もご用意しています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"まずは入口の鑑定で","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"彼の気持ちとこの恋の現在地を確認してみてください。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"その先は、鑑定を受けた後にご案内します。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"──","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"次の満月の夜、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"月の便りを届けます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"鑑定を受けなくても、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"凛はここにいます。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"境界のこちら側で、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"湖のほとりで、いつでも。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"またお話ししましょう。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"……凛の喉が、","size":"xs","color":"#C0C0C8","wrap":true,"align":"center"},{"type":"text","text":"小さくゴロゴロと鳴っています。","size":"sm","color":"#F5F0E8","wrap":true},{"type":"box","layout":"vertical","height":"12px","contents":[]},{"type":"text","text":"それはきっと、","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"あなたとの縁が","size":"sm","color":"#F5F0E8","wrap":true},{"type":"text","text":"静かに結ばれた音です。","size":"sm","color":"#F5F0E8","wrap":true}]}}', datetime('now'));